"""
ciphers.py

A simple cipher toolkit implementing Caesar, Vigenere, Rail-Fence, and Substitution ciphers.
Each cipher has encrypt, decrypt, and frequency_analysis functions.
"""

import string
from collections import Counter


# Utilities

def freq_analysis(text):
    """Frequency analysis helper to count letter frequencies in given text."""
    text = text.upper()
    counter = Counter(c for c in text if c in string.ascii_uppercase)
    total = sum(counter.values())
    return {ch: counter[ch] / total for ch in string.ascii_uppercase} if total > 0 else {ch: 0 for ch in string.ascii_uppercase}


# Caesar cipher

class CaesarCipher:
    """Caesar cipher with a numeric shift."""

    def __init__(self, shift):
        self.shift = shift % 26

    def encrypt(self, plaintext):
        ciphertext = []
        for ch in plaintext.upper():
            if ch in string.ascii_uppercase:
                shifted = chr((ord(ch) - 65 + self.shift) % 26 + 65)
                ciphertext.append(shifted)
            else:
                ciphertext.append(ch)
        return ''.join(ciphertext)

    def decrypt(self, ciphertext):
        plaintext = []
        for ch in ciphertext.upper():
            if ch in string.ascii_uppercase:
                shifted = chr((ord(ch) - 65 - self.shift) % 26 + 65)
                plaintext.append(shifted)
            else:
                plaintext.append(ch)
        return ''.join(plaintext)

    def frequency_analysis(self, text):
        return freq_analysis(text)


# Vigenère cipher

class VigenereCipher:
    """Vigenère cipher with keyword."""

    def __init__(self, key):
        self.key = key.upper()

    def _repeat_key(self, length):
        return (self.key * (length // len(self.key) + 1))[:length]

    def encrypt(self, plaintext):
        plaintext = plaintext.upper()
        key = self._repeat_key(len(plaintext))
        ciphertext = []
        for p, k in zip(plaintext, key):
            if p in string.ascii_uppercase:
                shift = ord(k) - 65
                c = chr((ord(p) - 65 + shift) % 26 + 65)
                ciphertext.append(c)
            else:
                ciphertext.append(p)
        return ''.join(ciphertext)

    def decrypt(self, ciphertext):
        ciphertext = ciphertext.upper()
        key = self._repeat_key(len(ciphertext))
        plaintext = []
        for c, k in zip(ciphertext, key):
            if c in string.ascii_uppercase:
                shift = ord(k) - 65
                p = chr((ord(c) - 65 - shift) % 26 + 65)
                plaintext.append(p)
            else:
                plaintext.append(c)
        return ''.join(plaintext)

    def frequency_analysis(self, text):
        return freq_analysis(text)


# Rail Fence cipher

class RailFenceCipher:
    """Rail Fence cipher with number of rails."""

    def __init__(self, rails):
        self.rails = rails

    def encrypt(self, plaintext):
        rails = [''] * self.rails
        rail_idx = 0
        direction = 1

        for ch in plaintext:
            rails[rail_idx] += ch
            rail_idx += direction

            if rail_idx == 0 or rail_idx == self.rails - 1:
                direction *= -1

        return ''.join(rails)

    def decrypt(self, ciphertext):
        n = len(ciphertext)
        pattern = [None] * n
        rail_idx = 0

        # mark the pattern
        direction = 1
        for i in range(n):
            pattern[i] = rail_idx
            rail_idx += direction
            if rail_idx == 0 or rail_idx == self.rails - 1:
                direction *= -1

        # count letters per rail
        rail_counts = [pattern.count(r) for r in range(self.rails)]

        # slice ciphertext into rails
        rails = []
        index = 0
        for count in rail_counts:
            rails.append(ciphertext[index:index+count])
            index += count

        # reconstruct plaintext
        pointers = [0] * self.rails
        plaintext = []
        for r in pattern:
            plaintext.append(rails[r][pointers[r]])
            pointers[r] += 1

        return ''.join(plaintext)

    def frequency_analysis(self, text):
        return freq_analysis(text)


# Substitution cipher

class SubstitutionCipher:
    """Substitution cipher with given mapping alphabet to cipher alphabet."""

    def __init__(self, mapping):
        """Mapping: dict or str that specifies the substitution alphabet.
        If str, must be 26 uppercase letters mapping A-Z to cipher letters."""
        if isinstance(mapping, str):
            mapping = mapping.upper()
            if len(mapping) != 26 or not all(c in string.ascii_uppercase for c in mapping):
                raise ValueError("Mapping string must be 26 uppercase letters.")
            self.mapping = {k: v for k, v in zip(string.ascii_uppercase, mapping)}
        elif isinstance(mapping, dict):
            self.mapping = {k.upper(): v.upper() for k, v in mapping.items()}
            if set(self.mapping.keys()) != set(string.ascii_uppercase):
                raise ValueError("Mapping dict must have all uppercase letters A-Z as keys.")
        else:
            raise TypeError("Mapping must be string or dict.")

        # Build reverse mapping for decryption
        self.reverse_mapping = {v: k for k, v in self.mapping.items()}

    def encrypt(self, plaintext):
        ciphertext = []
        for ch in plaintext.upper():
            if ch in string.ascii_uppercase:
                ciphertext.append(self.mapping[ch])
            else:
                ciphertext.append(ch)
        return ''.join(ciphertext)

    def decrypt(self, ciphertext):
        plaintext = []
        for ch in ciphertext.upper():
            if ch in string.ascii_uppercase:
                plaintext.append(self.reverse_mapping[ch])
            else:
                plaintext.append(ch)
        return ''.join(plaintext)

    def frequency_analysis(self, text):
        return freq_analysis(text)


if __name__ == '__main__':
    # Simple demonstration
    c = CaesarCipher(3)
    e = c.encrypt('HELLO WORLD!')
    d = c.decrypt(e)
    print(f"Caesar: {e} -> {d}")

    v = VigenereCipher('KEY')
    ev = v.encrypt('HELLO WORLD!')
    dv = v.decrypt(ev)
    print(f"Vigenere: {ev} -> {dv}")

    r = RailFenceCipher(3)
    er = r.encrypt('HELLO WORLD!')
    dr = r.decrypt(er)
    print(f"RailFence: {er} -> {dr}")

    sub_map = 'QWERTYUIOPASDFGHJKLZXCVBNM'
    s = SubstitutionCipher(sub_map)
    es = s.encrypt('HELLO WORLD!')
    ds = s.decrypt(es)
    print(f"Substitution: {es} -> {ds}")
